class Spreadsheet {
  private final int[][] cells;

  public Spreadsheet(int rows) {
    cells = new int[26][rows + 1];
  }

  public void setCell(String cell, int value) {
    cells[cell.charAt(0) - 'A'][Integer.parseInt(cell.substring(1))] = value;
  }

  public void resetCell(String cell) {
    setCell(cell, 0);
  }

  public int getValue(String formula) {
    int plus = formula.indexOf('+');
    return operand(formula.substring(1, plus)) + operand(formula.substring(plus + 1));
  }

  private int operand(String token) {
    if (Character.isLetter(token.charAt(0))) {
      return cells[token.charAt(0) - 'A'][Integer.parseInt(token.substring(1))];
    }
    return Integer.parseInt(token);
  }
}

